/**
 * Open a `step.{name}` span as a child of the run context. The orchestrator
 * makes this span active (context.with) across the step's rounds loop, so the
 * step's LLM `chat` spans and the bounded worker pools (which capture
 * `context.active()`) nest under it, giving the run -> step -> chat hierarchy.
 * The caller ends the span in a finally right after the rounds loop. Step spans
 * carry no gen_ai.* attributes (those belong on the chat / execute_tool spans).
 */
export function startStepSpan(tracer: Tracer, runCtx: Context, stepName: string): { span: Span; ctx: Context } {
  const span = tracer.startSpan(`step.${stepName}`, { kind: SpanKind.INTERNAL }, runCtx);
  const ctx = trace.setSpan(runCtx, span);
  return { span, ctx };
}

